import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

function hexToRgb(hex) {
  const value = String(hex || '#000000').replace('#', '');
  const normalized = value.length === 3
    ? value.split('').map((v) => v + v).join('')
    : value;
  const number = parseInt(normalized, 16);
  return [
    ((number >> 16) & 255) / 255,
    ((number >> 8) & 255) / 255,
    (number & 255) / 255,
  ];
}

function disposeObject(root) {
  root.traverse((object) => {
    if (object.geometry?.dispose) object.geometry.dispose();

    const material = object.material;
    if (Array.isArray(material)) {
      for (const item of material) item?.dispose?.();
    } else {
      material?.dispose?.();
    }
  });
}

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, BoxGeometry, Color, PointLight } = THREE;

  const root = new Group();
  root.name = 'nova-atelier-stat-tile';

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const visualSpec = config.intent?.visualSpec ?? {};
  const gradientStops = Array.isArray(visualSpec.gradientStops)
    ? visualSpec.gradientStops
    : [];

  const backdropColors = gradientStops
    .map((stop) => typeof stop === 'string' ? stop : stop?.color)
    .filter(Boolean);

  const backdropTop = backdropColors[backdropColors.length - 1] ?? colors.ink;
  const backdropBottom = backdropColors[0] ?? colors.surface;

  const backdropMaterial = new MeshBasicNodeMaterial();
  const backdropUV = uv();
  const bottom = hexToRgb(backdropBottom);
  const top = hexToRgb(backdropTop);

  backdropMaterial.colorNode = mix(
    vec3(bottom[0], bottom[1], bottom[2]),
    vec3(top[0], top[1], top[2]),
    smoothstep(0.0, 1.0, backdropUV.y),
  );

  const backdrop = new Mesh(new PlaneGeometry(7, 6), backdropMaterial);
  backdrop.name = 'machined-stage-backdrop';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  const panelMaterial = new MeshStandardNodeMaterial();
  panelMaterial.color = new Color(colors.ink);
  panelMaterial.metalness = 0.45;
  panelMaterial.roughness = 0.62;

  const panel = new Mesh(new BoxGeometry(2.25, 1.38, 0.14), panelMaterial);
  panel.name = 'stat-tile-machined-surface';
  panel.position.set(0, 0, -0.12);
  root.add(panel);

  const edgeMaterial = new MeshBasicNodeMaterial({
    color: new Color(colors.accent),
    transparent: true,
    opacity: 0.22,
  });

  const edgeTop = new Mesh(new BoxGeometry(2.18, 0.025, 0.035), edgeMaterial);
  const edgeBottom = new Mesh(new BoxGeometry(2.18, 0.025, 0.035), edgeMaterial);
  const edgeLeft = new Mesh(new BoxGeometry(0.025, 1.32, 0.035), edgeMaterial);
  const edgeRight = new Mesh(new BoxGeometry(0.025, 1.32, 0.035), edgeMaterial);

  edgeTop.position.set(0, 0.665, -0.035);
  edgeBottom.position.set(0, -0.665, -0.035);
  edgeLeft.position.set(-1.09, 0, -0.035);
  edgeRight.position.set(1.09, 0, -0.035);

  root.add(edgeTop, edgeBottom, edgeLeft, edgeRight);

  const shadowMaterial = new MeshBasicNodeMaterial({
    color: new Color(colors.surface),
    transparent: true,
    opacity: 0.48,
    depthWrite: false,
  });

  const shadow = new Mesh(new THREE.CircleGeometry(1.5, 64), shadowMaterial);
  shadow.name = 'stat-tile-contact-shadow';
  shadow.scale.set(1.25, 0.34, 1);
  shadow.position.set(0, -0.78, -0.2);
  root.add(shadow);

  const rim = new PointLight(new Color(colors.accent), 0.72, 3.5);
  rim.name = 'stat-tile-accent-rim';
  rim.position.set(1.5, 1.1, 1.3);
  root.add(rim);

  const fill = new PointLight(new Color(colors.paper), 0.42, 4);
  fill.name = 'stat-tile-paper-fill';
  fill.position.set(-1.5, 0.6, 1.7);
  root.add(fill);

  const loadedResources = [];
  const timelines = [];
  const primitiveCleanups = [];
  const baseY = root.position.y;

  const meshUrl = config.meshUrl;
  if (meshUrl && ctx.glbLoader?.loadGLB) {
    ctx.glbLoader.loadGLB(meshUrl)
      .then((gltf) => {
        if (!gltf?.scene) return;
        const scene = gltf.scene;
        scene.name = 'stat-tile-gear';
        root.add(scene);
        loadedResources.push(scene);
      })
      .catch(() => {});
  }

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const role = item.role ?? 'body';
    const fontSize = item.typography?.fontSize ??
      (role === 'hero' || role === 'headline' ? 0.34 : 0.13);

    const textObject = ctx.fontAtlas?.createText?.(item.text, {
      fontSize,
      color: item.typography?.color ?? colors.paper,
      align: item.typography?.align ?? 'center',
      maxWidthPx: item.typography?.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx,
    });

    if (textObject) {
      textObject.position.set(0, item.position?.y ?? 0, 0.12);
      root.add(textObject);
      loadedResources.push(textObject);
    }
  }

  for (const primitive of config.cinematicPrimitives ?? []) {
    const applyPrimitive = ctx.primitives?.[primitive.name];
    if (typeof applyPrimitive !== 'function') continue;

    const result = applyPrimitive(root, primitive.params ?? {});
    if (result?.timeline) timelines.push(result.timeline);
    if (typeof result?.cleanup === 'function') {
      primitiveCleanups.push(result.cleanup);
    }
  }

  const focusEdges = [edgeTop, edgeBottom, edgeLeft, edgeRight];

  root.userData.handlers = {
    hover: (active = true) => {
      const targetY = active ? baseY + 0.15 : baseY;
      const timeline = gsap.timeline();
      timeline.to(root.position, {
        y: targetY,
        duration: 0.7,
        ease: 'power3.out',
      });
      timeline.to(root.rotation, {
        x: active ? -0.035 : 0,
        y: active ? 0.035 : 0,
        duration: 0.3,
        ease: 'power2.out',
      }, 0);
      timelines.push(timeline);
    },

    click: () => {
      const timeline = gsap.timeline();
      timeline.to(root.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'power2.out',
      });
      timeline.to(root.scale, {
        x: 1.04,
        y: 1.04,
        z: 1.04,
        duration: 0.22,
        ease: 'back.out(2)',
      });
      timeline.to(root.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.68,
        ease: 'power4.out',
      });
      timelines.push(timeline);
      ctx.emit?.('hub-home.select', { node: root.name });
    },

    focus: (active = true) => {
      for (const edge of focusEdges) {
        if (edge.material) edge.material.opacity = active ? 0.9 : 0.22;
      }
    },
  };

  root.userData.cleanup = () => {
    for (const timeline of timelines) timeline?.kill?.();
    for (const cleanup of primitiveCleanups) cleanup();

    for (const resource of loadedResources) {
      if (resource !== root) disposeObject(resource);
    }

    disposeObject(root);
  };

  return root;
}
